import React, {useState} from 'react'

function Form1(props) {
  // 상태 변수선언 - [변수명, 함수명] = useState(''); > state초기값 지정
  const [name, setName] = useState('');

  // nameChage - 사용자가 입력 양식에 글 입력함과 동시에 함수 실행
  const nameChange=(e)=>{
    setName(e.target.value);  //상태값을 함수에 담기
  }

  // 이름 초기화 함수 nameReset
  const nameReset =()=>{
    // alert('초기화 버튼입니다');
    setName('');  //상태관리 함수를 호출하면 ''빈 값을 너어줌. ==값 비우기
  }
  return (
    <>
      <h4 className='title4'>1. 기본 입력폼 양식</h4>
      <form>
        <p>이름을 작성하세요</p>
        <p>입력한 값 : (name)</p>
        <input type='text' value={name} name='name' onChange={nameChange} />
        <input type='button' value='초기화' onClick={nameReset} />
      </form>
    </>
  )
}

export default Form1;