import React, {useState, useEffect} from 'react'
// import dummy from './data/noodle.json'

function Noodle(props) {

  const [noodles, setNoodles] = useState([]); //상태값 초기화
  
    //비동기 방식으로 데이터 불러오기
    useEffect(()=>{
      fetch(`${process.env.PUBLIC_URL}/data/noodle.json`)
      .then(response => response.json())
      .then(json => setNoodles(json))
      .catch(err => console.error('데이터불러오기 실패 : ', err));
    }, []);

  return (
    <>
      <h4>Noodle데이터 출력</h4>
      <ul className=''>
        {
          noodles.length > 0 && noodles[2].data.map(noodle => (
            <li key={noodle.num}>
              name: {noodle.name}
              company: {noodle.company}
              kind: {noodle.kind}
              price: {noodle.price}원 
              e_date: {noodle.e_date}
              reg_date: {noodle.reg_date} <br />
            </li>
          ))
        }
      </ul>
    </>
  )
}

export default Noodle