import React, {useState, useEffect} from 'react'
import dummy from './data/book_store.json'

function BookStore(props) {

  const [books, setBooks] = useState([]); //상태값 초기화

  //비동기 방식으로 데이터 불러오기
  useEffect(()=>{
    // fetch('./data/book_store.json') //방법1
    fetch(`${process.env.PUBLIC_URL}/data/book_store.json`)
    .then(response => response.json())
    .then(json => setBooks(json))
    .catch(err => console.error('데이터불러오기 실패 : ', err));
  }, []);

  return (
    <>
      <h3>book_store json데이터 출력하기</h3>
      <p>1. 정적 - 파일이 작은 경우 import방식으로 데이터 출력</p>
      <p>map함수와 slice메서드로 원하는 개수만 불러오기</p>
      <ul>
        <li>slice(start, end)</li>
        <li>start: 포함O 시작 인덱스</li>
        <li>end: 포함X 종료 인덱스</li>
        <li>slic(0,5): 0번 인덱스 ~ 4번 인덱스값 까지 총 5개의 값을 가져오겠다</li>
      </ul>

      <h4>BookStore</h4>
      <ul className='list01'>
        {
          dummy[2].data.slice(0,5).map(book=>(
            <li>
              num:{book.code}
              지점명: {book.name}
              시/도/광역시: {book.area1}
              군/구: {book.area2}
              읍/면/동: {book.area3}
              주문수량: {book.book_cnt}
              주문자: {book.owner_nm}
              연락처: {book.tel_num}
            </li>
          ))
        }
      </ul>

      <p>2. fetch를 활용한 비동기 방식으로 데이터 로딩하기</p>
      <ul className=''>
        {/* {
          books.length > 0 && books[2].data.map(book => (
            <li key={book.code}>
              num:{book.code}
              지점명: {book.name}
              시/도/광역시: {book.area1}
              군/구: {book.area2}
              읍/면/동: {book.area3}
              주문수량: {book.book_cnt}
              주문자: {book.owner_nm}
              연락처: {book.tel_num} <br />
            </li>
          ))
        } */}

        {
          books[2]?.data?.map(book => (
            <li key={book.code}>
              num:{book.code}
              지점명: {book.name}
              시/도/광역시: {book.area1}
              군/구: {book.area2}
              읍/면/동: {book.area3}
              주문수량: {book.book_cnt}
              주문자: {book.owner_nm}
              연락처: {book.tel_num} <br />
            </li>
          ))
        }
      </ul>
    </>
  )
}

export default BookStore