import React, {useState, useEffect} from 'react'

function Fruits(props) {

  const [fruits, setFruits] = useState([]); //상태값 초기화
  
    //비동기 방식으로 데이터 불러오기
    useEffect(()=>{
      fetch(`${process.env.PUBLIC_URL}/data/fruits.json`)
      .then(response => response.json())
      .then(json => setFruits(json))
      .catch(err => console.error('데이터불러오기 실패 : ', err));
    }, []);

  return (
    <>
      <h4>orders데이터 출력</h4>
      <ul className=''>
        {
          fruits.length > 0 && fruits[2].data.map(fruit => (
            <li key={fruit.num}>
              번호: {fruit.num}  |  
              이름: {fruit.name}  |  
              금액: {fruit.price}  |  
              색상: {fruit.color}  |  
              나라: {fruit.country} <br />
            </li>
          ))
        }
      </ul>
    </>
  )
}

export default Fruits