import React from 'react'
import dummy from './data/goods.json'

function Goods(props) {
  return (
    <>
      <h4>Goods데이터 출력</h4>
      <ul className='list01'>
        {
          dummy[2].data.map(goods=>(
            <li key={goods.g_code}>
              코드번호: {goods.g_code}
              메뉴명: {goods.g_name} 
              금액: {goods.g_cost} 
            </li>
          ))
        }
      </ul>
    </>
  )
}

export default Goods