import React, {useState, useEffect} from 'react'

function Orders(props) {

  const [orders, setOrders] = useState([]); //상태값 초기화
  
    //비동기 방식으로 데이터 불러오기
    useEffect(()=>{
      fetch(`${process.env.PUBLIC_URL}/data/orders.json`)
      .then(response => response.json())
      .then(json => setOrders(json))
      .catch(err => console.error('데이터불러오기 실패 : ', err));
    }, []);

  return (
    <>
      <h4>orders데이터 출력</h4>
      <ul className=''>
        {
          orders.length > 0 && orders[2].data.map(order => (
            <li key={order.o_num}>
              o_day: {order.o_day}  /  
              c_name: {order.c_name}  /  
              g_code: {order.g_code}  /  
              o_num: {order.o_num} <br />
            </li>
          ))
        }
      </ul>
    </>
  )
}

export default Orders