import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation, Pagination, Scrollbar, Autoplay } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';

/* 외부사이트 연결시,
    <a href='https://www.naver.com' title=''><img src='' alt='' /></a>*/
/* 부모요소 태그에 옵션 작성 -> 좌우버튼, 콘트롤버튼, 자동슬라이드, 터치 슬라이드 동작
    <Swiper 
      modules={[Navigation, Pagination, Scrollbar, Autoplay]} //사용할 모듈 추가
      spaceBetween={0}              //슬라이드 이미지간격
      slidesPerView={1}             //한페이지에 보여질 이미지 개수
      navigation                    //메뉴
      autoplay={{delay:3000}}       //자동슬라이드시간
      paginaton={{clickable:true}}  //콘트롤버튼 클릭가능 여부
      scrollbar={{draggable:true}}  //터치스크롤 여부
      className="mslide"
    >   */


function Main(props) {
  return (
    <main>
      메인 서식
      <section>
        <Swiper 
          modules={[Navigation, Pagination, Scrollbar, Autoplay]} //사용할 모듈 추가
          spaceBetween={0}              //슬라이드 이미지간격
          slidesPerView={1}             //한페이지에 보여질 이미지 개수
          navigation                    //메뉴
          autoplay={{delay:3000}}       //자동슬라이드시간
          paginaton={{clickable:true}}  //콘트롤버튼 클릭가능 여부
          scrollbar={{draggable:true}}  //터치스크롤 여부
          loop
          className="mslide"
        >
          <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide1.jpg`} alt='배너1' /></SwiperSlide>
          <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide2.jpg`} alt='배너2' /></SwiperSlide>
          <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide3.jpg`} alt='배너3' /></SwiperSlide>
          <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide4.jpg`} alt='배너4' /></SwiperSlide>
        </Swiper>
      </section>
    </main>
  );
}

export default Main;