import React, { useState } from 'react'

function Form2(props) {
  // 변수 선언
  let header = '';

  // 상태관리값 선언과 초기값 설정
  const [name, setName] = useState('');
  const [pw_name, setPw] = useState('');

  // nameChange함수 작성
  const nameChange=(e)=>{//이름을 지정하기 위한 함수
    setName(e.target.value);  //이름 값 저장
  }

  // pw를 지정하기 위한 함수
  const pwChange=(e)=>{//비밀번호를 지정하기 위한 함수
    setPw(e.target.value);  //pw저장
  }

  // 조건식을 사용해 값이 있을 경우에만 출력, 그렇지 않으면 공백
  if(name){
    header=<p>사용자가 입력한 이름은 {name}dlrh, 비밀번호는 {pw_name}입니다</p>
  }else{
    header="";
  }

  //onDataReset 클릭시, name, pw_name초기화
  const onDataReset=(e)=>{
    setName('');
    setPw('');
  }

  return (
    <>
    <h4 className='title4'>2. if문으로 조건식 작성</h4>

    {/* name, pw_name출력할 곳 */}
    {header}

    <form>
      <p>
        <label for="id_name">ID : </label>
        <input type='text' id='id_name' name='id_name' value={name} onChange={nameChange} />
      </p>
      <p>
        <label for="pw_name">PW : </label>
        <input type='text' id='pw_id' name='pw_name' value={pw_name} onChange={pwChange} />
      </p>
    </form>
    <p>
      <button type='button' onClick={onDataReset}>데이터 입력 초기화</button>
    </p>
    </>
  )
}

export default Form2;