import React, { useState, useEffect } from 'react'

function UseEffect4(props) {

  const [width, setWidth] = useState(window.innerWidth);
  const [height, setHeight] = useState(window.innerHeight);
  useEffect(()=>{
    const handleResize=()=>{
      setWidth(window.innerWidth);  //padding값 포함
      setHeight(window.innerHeight);
    }
    // 화면크기 조정시 가로,세로 크기값 저장
    window.addEventListener('resize', handleResize);
    return()=>{
      window.addEventListener('resize', handleResize);
    }
  }, []);

  return (
    <>
      <h3>useEffect예제4 - 윈도우 리사이즈 이벤트 감지</h3>
      <p>브라우저의 가로크기를 조절해 값 확인</p>
      <p>현재창 너비: {width}px 입니다</p>
      <p>현재창 높이: {height}px 입니다</p>

      <ul>
        <li>화면 로드시 현재 window.innerWidth, window.innerHeight를 상태에 저장</li>
        <li>브라우저 창 크기가 변경되면 resize 이벤트 발생</li>
        <li>handleResize 함수가 실행되어 width, height 상태를 업데이트</li>
        <li>UI에 즉시 변경된 창 크기가 반영</li>
        <li>컴포넌트가 제거될 때 removeEventListener로 이벤트 정리</li>
        <li>브라우저 크기가 다시 변경되면 화면이 다시 렌더링 됨</li>
      </ul>
    </>
  )
}

export default UseEffect4