import Tabmnu3 from './0102/Tabmnu3';
import Music from './0105/Music';
import Modal from './0107/Modal';

import { useEffect, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBars, faTimes } from '@fortawesome/free-solid-svg-icons';

function App() {

  // 변수
  const [visible, setVisible] = useState(false);  // [1] TOP버튼 상태 변수
  const [menuOpen, setMenuOpen] = useState(false); // [4] 메뉴

  // [1] TOP버튼
  const scrollTop =()=> { // scroll기능이 들어간 함수
    window.scrollTo({top:0, behavior:'smooth'});
  }
  useEffect(() => { // useEffect활용 > 콤포넌트 생성시 이벤트 기능 추가
    const handleScroll =()=> {
      setVisible(window.scrollY>300);
    }
    window.addEventListener('scroll', handleScroll);
    return ()=> window.removeEventListener('scroll', handleScroll);
  },[])

  // [2] 새로고침
  const handleRefrash =()=> {
    window.location.reload();
  }

  // [3] 메뉴목록 작성 - 배열객체 사용
  const menuItems = [
    {id:'day01', label:'1일차 학습'},
    {id:'day02', label:'2일차 학습'},
    {id:'day03', label:'3일차 학습'},
    {id:'day04', label:'4일차 학습'},
    {id:'day05', label:'5일차 학습'},
    {id:'day06', label:'6일차 학습'},
    {id:'day07', label:'7일차 학습'},
    {id:'day08', label:'8일차 학습'},
    {id:'day09', label:'9일차 학습'},
    {id:'day10', label:'10일차 학습'},
    {id:'day11', label:'11일차 학습'},
    {id:'day12', label:'12일차 학습'},
    {id:'day13', label:'13일차 학습'},
    {id:'day14', label:'14일차 학습'},
    {id:'day15', label:'15일차 학습'}
  ]

  // [4] 메뉴목록 클릭 > 해당 id값을 찾아 이동
  const handleMenuClick =(id)=> {
    const el = document.getElementById(id);
    if(el){
      const y = el.getBoundingClientRect().top + window.pageYOffset-60;
      window.scrollTo({top:y, behavior:'smooth'});
      setMenuOpen(false); //메뉴클릭시 메뉴목록 닫기
    }
  }

  return (
    <>
      <header className="header">
        <h1>리액트 학습하기</h1>

        {/* 전체메뉴(토글)클릭시 해당 함수 호출 > .gnb위치 right:0이 되어야 나옴 */}
        <button onClick={()=> setMenuOpen(!menuOpen)}
          style={{
            fontSize:'38px', color:'#fff',
            position:'fixed', top:'16px', right:'20px',
            border:'none', background:'none',
            cursor:'pointer',
            zIndex:'1000'
          }}
        ><FontAwesomeIcon icon={faBars} /></button>

        {/* 학습목차 메뉴 목록 */}
        <nav className='gnb'
          style={{
            right:menuOpen ? '0px':'-100%'
          }}
        >
          {/* 닫기버튼 */}
          <button className='close_btn'
            onClick={()=>setMenuOpen(false)}
          >
            <FontAwesomeIcon icon={faTimes}
              style={{fontSize: '38px'}}
            />
          </button>
          {/* 메뉴목록 - menuItems배열객체 */}
          <ul>
            {menuItems.map(item => (
              <li key={item.id}>
                <button onClick={()=>handleMenuClick(item.id)}>
                  {item.label}
                </button>
              </li>
            ))}
          </ul>
        </nav>
      </header>

      <main>
        <h2 className="title2" id='day01'>1일차 학습 1219 - 리액트 소개와 nodejs설치, 프로젝트 설치, 실행방법, 리액트 jsx 문법, 콤포넌트 개념, css적용방법, 이미지 삽입방법</h2>
        <Class0 /><hr />
        <Class01 /><hr />
        <Class02 /><hr />
        <Class03 /><hr />
        실습예제 - 모바일 동물병원

        <h2 className="title2" id='day02'>2일차 학습 1222 - 리액트 배포방법과 일반돔, 가상돔 이해하기, props, state, event</h2>
        <Class04 /><hr />
        <Class05 /><hr />
        <Class06 /><hr />
        <Class07 /><hr />
        <Class08 />

        <h2 className="title2" id='day03'>3일차 학습 1223 - 이벤트, 폼태그</h2>
        <Event /><hr />
        <Form /><hr />

        <h2 className="title2" id='day04'>4일차 학습 1224 - 라우터, 스와이퍼</h2>
        <Router /><hr />

        <h2 className="title2" id='day05'>5일차 학습 1226 - 배열 데이터</h2>
        <Array1 /><hr />
        <Yellow /><hr />

        <h2 className="title2" id='day06'>6일차 학습 1229 - 배열 데이터 복습, React Hooks(useState, useRef, userEffect)</h2>
        <p>React Hooks는 기존 class형 콤포넌트에서 사용하던 문법을 함수형 콤포넌트에서도 사용할 수 있도록 추가된 문법 몇가지를 말함. 16.8버전 부터 적용됨. (2일차 참고, 피그마 참고)</p>
        <Array2 /><hr />
        <Usestate /><hr />
        <LoginForm /><hr />
        <UseRefDom /><hr />
        <Array3 /><hr />

        <h2 className="title2" id='day07'>7일차 학습 1230 - 배열 데이터 응용하시</h2>
        <a href='https://16automne.github.io/perfume2025' title=''>상품 입력/출력/삭제 기능 구현하기</a>
        <ul>
          <li><a href='https://sihi-j.github.io/Banila/' title='장 서현'>바닐라코</a></li>
          <li><a href='https://lynsunwoo.github.io/Tomford/' title='선우 린'>톰포드</a></li>
          <li><a href='https://ijh950809-dotcom.github.io/olive/' title='임지희'>올리브영</a></li>
          <li><a href='https://hrkim0413.github.io/bakery/' title='김혜련'>베이커리</a></li>
          <li><a href='https://youngchild-cloud.github.io/musinsa_react/' title='김영찬'>무신사</a></li>
        </ul>

        <h2 className="title2" id='day08'>8일차 학습 1231 - DB에서 저장한 json데이터 map함수로 출력하기, HOOKS(useEffect), 오늘의 할일(TodoList)</h2>
        <Json /><hr />
        <LifeCycle /><hr />
        <UseEffect1 /><hr />
        <UseEffect2 /><hr />
        <UseEffect3 /><hr />
        <UseEffect4 /><hr />
        <hr />

        <h2 className="title2" id='day09'>9일차 학습 0102 - 탭콘텐츠 구현하기</h2>
        <Tabmnu1 /><hr />
        <Tabmnu2 /><hr />
        <Tabmnu3 /><hr />

        <h2 className="title2" id='day10'>10일차 학습 0105 - json데이터(music)출력하기, API를 활용한 영화 소개 페이지</h2>
        <Music />

        <h2 className="title2" id='day11'>11일차 학습 0106 - API를 활용한 영화소개 페이지 구현하기</h2>
        <a href='https://16automne.github.io/movie2026/' title='페이지로 이동하기'>API영화 사이트 보기</a>

        <h2 className="title2" id='day12'>12일차 학습 0107 - Top버튼, 새로고침(f5)기능, 모바일 내비게이션, 모달윈도, frontend, backend 셋팅과 실행</h2>
        {visible && (
          <button
          onClick={scrollTop} //{객체} *객체란 함수,배열, 변수, css서식 ...
            style={{
              position:'fixed', right:'20px', bottom:'100px',
              padding:'15px 12px',
              fontSize:'16px', color:'#333',
              backgroundColor:'#fff', border:'1px solid #ccc', boxShadow:'0px 3px 6px #ccc',
              cursor:'pointer',
              zIndex:'1000'
            }}
          >Top</button>
        )}
        <Modal />
        <ol>
          <li>useState 훅 사용 : showModal이라는 상태 변수와 setShowModal이라는 상태 변경 함수를 선언함. 초기값을 true로 설정하면 모달이 처음부터 표시되고, false로 설정하면 버튼 클릭 시에만 표시</li>
          <li>모달 트리거: '모달 열기' 버튼을 클릭하면 setShowModal (true)가 실행되어 모달이 열림</li>
          <li>조건부 렌더링 {/* {showModal && (...)} */}구문을 사용해 showModal이 true일 때만 모달 표시</li>
          <li>모달 스타일링: 부모박스요소는 고정배치, 배경색 검정, 쿠명도 적용, 내부 박스 요소는 화면 중앙에 배치되도록 흰색 배경 적용</li>
          <li>모달 닫기: '닫기'버튼 클릭시 setShowModal(false)를 실행하여 모달을 숨기기</li>
        </ol>

        <h2 className="title2" id='day13'>13일차 학습 0108</h2>
        <h2 className="title2" id='day14'>14일차 학습 0109</h2>
        <h2 className="title2" id='day15'>15일차 학습 0110</h2>
      </main>

      <footer className="footer">
        <button onClick={handleRefrash}>12일차 - 새로고침 (F5)</button>
        <address>Copyright&copy;2025 React학습목차 allrights reserved.</address>
      </footer>
    </>
  );
}

export default App;
