import React, {useState} from 'react'

function Form5(props) {

  // 상태 변수
  const [formData, setFormData] = useState({
    name: '',
    age: null
  });

  // 입력을 하면 각 이름, 나이 저장
  const nameChange=(e)=>{
    const {name, value} = e.target;
    setFormData(prev=>({
      ...prev,
      [name]:value
    }));
  }

  // 전송버튼 클릭시 데이터 유효성 검사
  const dataSubmit=(e)=>{
    e.preventDefault();

    const age = formData.age;
    if(!Number(age)){
      alert('나이는 숫자로 입력해주세요');
    } else{
      console.log('전송데이터: ', formData);
    }
  }
  return (
    <>
    <h4 className='title4'>5. 데이터 전송시 유효성 검사</h4>
    <p>* 이름, 나이 입력시 이름은 문자, 나이는 숫자로 입력해야 하되 나이가 숫자 데이터가 아니면 오류메세지가 나올 수 있도록 해야 함</p>
    <p>* if문을 사용해 state값 중 나이가 숫자가 아니면 'alert매서드'로 경고창을 띄움</p>
    <p>* 나이는 숫자 데이터기때문에 Number형으로 변환해야 함</p>

    <form onSubmit={dataSubmit}>
      출력 내용:
      <p><strong>이름: {formData.name}</strong></p>
      <p><strong>나이: {formData.age}</strong></p>

      <p>
        <label>이름을 입력하세요</label>
        <input type='text' name='name' id='name' onChange={nameChange} value={formData.name} />
      </p>

      <p>
        <label>나이를 입력하세요</label>
        <input type='text' name='age' id='age' onChange={nameChange} value={formData.age || ''} />
      </p>

      <p>
        <button type='submit'>전송하기</button>
      </p>
    </form>
    </>
  )
}

export default Form5